36: import { getType } from '@/utils/index.js'
37: export default {
38:   name: 'ZsOperateColumn',
39:   inject: {
40:     zsTable: {
41:       default: null
42:     }
43:   },
44:   data() {
45:     return {}
46:   },
47:   props: {
48:     // 模块名
49:     moduleName: {
50:       type: String,
51:       required: false
52:     },
53:     // 业务名
54:     businessName: {
55:       type: String,
56:       required: false
57:     },
58:     // 权限前缀（与 moduleName:businessName 不一致时传入，如 pricemng:recordPriceMng）
59:     permsPrefix: {
60:       type: String,
61:       required: false
62:     },
63:     buttons: {
64:       type: Array,
65:       default: () => []
66:     },
67:     showAll: {
68:       type: Boolean,
69:       default: false
70:     },
71:     width: {
72:       type: [String, Number],
73:       default: undefined
74:     },
75:     fixed: {
