77:       default: 'right'
78:     }
79:   },
80:   computed: {
81:     // 纯计算：有显式 width 用 width，否则按各行可见按钮文字估算最大宽度。
82:     // 仅依赖 tableData/buttons，测量结果不反馈回布局，故不会触发循环。
83:     columnWidth() {
84:       if (this.width != null) return this.width
85:       const rows = this.zsTable?.tableData || []
86:       const sampleRows = rows.length ? rows : [{}]
87:       return sampleRows.reduce((max, row) => Math.max(max, this.calcRowActionWidth(row)), 96)
88:     }
89:   },
90:   methods: {
91:     getLabel(button, row) {
92:       return getType(button.label) == 'function' ? button.label(row) : button.label
93:     },
94:     /** 操作列「删除」统一 danger + plain，与 table.js deleteButton 一致 */
95:     getButtonAttrs(button, row) {
96:       const attrs = { ...(button.attrs || {}) }
97:       if (this.getLabel(button, row) === '删除') {
98:         attrs.type = attrs.type || 'danger'
99:         attrs.plain = true
100:       }
101:       return attrs
102:     },
103:     getTextLength(text = '') {
104:       // 中文按双字符估算，避免列宽偏小导致按钮文字拥挤
105:       return String(text).replace(/[^\x00-\xff]/g, 'xx').length
106:     },
107:     getButtonWidthByLabel(label) {
108:       const textLength = this.getTextLength(label)
109:       return Math.max(42, textLength * 7 + 14)
110:     },
111:     getRowButtons(row) {
112:       return this.buttons.filter((button) => {
113:         if (getType(button.visible) == 'function') {
114:           return button.visible(row)
115:         }
116:         if (!button.permission) return true
117:         const prefix = this.permsPrefix || `${this.moduleName}:${this.businessName}`
118:         const perms = [`${prefix}:${button.permissionType}`]
119:         return this.checkPermission(perms, this.getLabel(button, row))
120:       })
121:     },
122:     getVisibleButtons(row) {
123:       const buttons = this.getRowButtons(row)
124:       return this.showAll ? buttons : (buttons.length > 3 ? buttons.slice(0, 2) : buttons.slice(0, 3))
125:     },
126:     calcRowActionWidth(row) {
127:       const buttons = this.getRowButtons(row)
128:       const visibleButtons = this.showAll ? buttons : (buttons.length > 3 ? buttons.slice(0, 2) : buttons.slice(0, 3))
129:       const labelWidth = visibleButtons.reduce((sum, button) => {
130:         return sum + this.getButtonWidthByLabel(this.getLabel(button, row))
131:       }, 0)
132:       const gapWidth = Math.max(visibleButtons.length - 1, 0) * 8
133:       const dropdownWidth = !this.showAll && buttons.length > 3 ? 42 + 8 : 0
134:       const cellPaddingWidth = 32
135:       const widthBuffer = 8
136:       return Math.max(96, labelWidth + gapWidth + dropdownWidth + cellPaddingWidth + widthBuffer)
137:     }
138:   }
139: }
